function sumLayer(key){return state.regions.reduce((total,r)=>total+Object.values(r[key]).reduce((s,v)=>s+v,0),0)}
function infrastructureCapacity(r){const i=r.infrastructure;return {power:i.powerPlants*ECONOMY_CONFIG.infrastructure.powerPlantOutput,grid:i.powerGrid*ECONOMY_CONFIG.infrastructure.gridCapacity,compute:i.dataCenters*34,communication:i.communication*20}}
function calculateQuarter(r){const c=ECONOMY_CONFIG,i=r.infrastructure,cap=infrastructureCapacity(r),resources=r.resources,compute=r.computeLayers,prod=r.productivityLayers;const powerProduction=c.power.baseProduction+i.powerPlants*c.infrastructure.powerPlantOutput;const powerConsumption=i.dataCenters*c.infrastructure.dataCenterPower+i.communication*c.infrastructure.communicationPower+i.chipFactories*c.infrastructure.chipPower+i.cooling*c.infrastructure.coolingPower;const gridLimit=i.powerGrid*c.infrastructure.gridCapacity;const storage=Math.min(i.storage*c.infrastructure.storageCapacity,powerProduction*c.power.storageDischarge);const availablePower=Math.min(powerProduction+storage,gridLimit);const shortage=Math.max(0,powerConsumption-availablePower);const powerRatio=powerConsumption?clamp(availablePower/powerConsumption,0,1):1;const availableCompute=Math.round(i.dataCenters*34*powerRatio);const computeDemand=c.compute.generalDemand+r.population*.025;const computeRatio=clamp(availableCompute/computeDemand,0,1);const aiTraining=Math.round(availableCompute*c.compute.aiTrainingShare*computeRatio);const aiInference=Math.round(availableCompute*c.compute.aiInferenceShare*computeRatio);const research=Math.round(availableCompute*c.compute.researchShare*computeRatio);const military=Math.round(availableCompute*c.compute.militaryShare*computeRatio);const conversion=(aiTraining*c.ai.trainingToProductivity+aiInference*c.ai.inferenceToProductivity)*c.ai.computeEfficiency;const industrial=clamp(prod.industrialAutomation+conversion*c.productivity.industrialOutput,0,100);const agricultural=clamp(prod.agriculturalAutomation+conversion*c.productivity.agricultureOutput,0,100);const researchEfficiency=clamp(prod.researchEfficiency+research*c.productivity.researchOutput/100,0,100);const militaryAI=clamp(prod.militaryAI+military*c.productivity.militaryOutput/100,0,100);const admin=clamp(prod.administrationEfficiency+conversion*c.productivity.administrationOutput,0,100);const medical=clamp(prod.medicalProductivity+conversion*c.productivity.medicalOutput,0,100);const industrialGain=(industrial/100)*r.resources.industrialMaterials*.06;const foodGain=(agricultural/100)*r.resources.food*.025;const foodNeed=r.population*c.society.foodNeedPerPopulation/4;const waterNeed=r.population*c.society.waterNeedPerPopulation/4;resources.food=clamp(resources.food+foodGain-foodNeed,0,9999);resources.water=clamp(resources.water-waterNeed+foodGain*.3,0,9999);resources.industrialMaterials=clamp(resources.industrialMaterials+industrialGain-r.resources.industrialMaterials*.018,0,9999);resources.minerals=clamp(resources.minerals-(i.chipFactories*3),0,9999);const resourceShortage=resources.food<foodNeed||resources.water<waterNeed;const socialChange=shortage>0?-c.power.shortageStabilityLoss/2:resourceShortage?-c.society.stabilityFromShortage/2:c.society.stabilityFromSurplus/2;r.power={production:Math.round(powerProduction),consumption:Math.round(powerConsumption),available:Math.round(availablePower),shortage:Math.round(shortage)};compute.general=Math.round(availableCompute*.34);compute.aiTraining=aiTraining;compute.aiInference=aiInference;compute.research=research;compute.military=military;prod.industrialAutomation=industrial;prod.agriculturalAutomation=agricultural;prod.researchEfficiency=researchEfficiency;prod.militaryAI=militaryAI;prod.administrationEfficiency=admin;prod.medicalProductivity=medical;r.socialCapability=Math.round((admin+medical+r.stability)/3);r.stability=clamp(r.stability+socialChange-(shortage?c.power.shortageProductivityLoss/2:0),0,100);r.energy=Math.round(powerRatio*100);r.compute=Math.round(availableCompute);r.productivity=Math.round((industrial+agricultural+researchEfficiency+admin)/4);r.technology=clamp(Math.round(researchEfficiency),0,100);r.military=clamp(Math.round(militaryAI),0,100);r.network.flows=[{from:'power',to:'infrastructure',value:availablePower},{from:'infrastructure',to:'compute',value:availableCompute},{from:'compute',to:'ai',value:aiTraining+aiInference},{from:'ai',to:'productivity',value:Math.round(conversion)},{from:'productivity',to:'society',value:r.socialCapability}];return {powerProduction,powerConsumption,shortage,availableCompute,conversion,resourceShortage}}
function settleQuarter(){const reports=state.regions.map(r=>calculateQuarter(r));const p=reports.reduce((s,x)=>s+x.powerProduction,0),consumption=reports.reduce((s,x)=>s+x.powerConsumption,0),available=reports.reduce((s,r)=>s+r.powerProduction-r.shortage,0);state.global.power={production:Math.round(p),consumption:Math.round(consumption),available:Math.round(available),shortage:Math.round(Math.max(0,consumption-available))};state.global.resources={food:Math.round(state.regions.reduce((s,r)=>s+r.resources.food,0)),minerals:Math.round(state.regions.reduce((s,r)=>s+r.resources.minerals,0)),water:Math.round(state.regions.reduce((s,r)=>s+r.resources.water,0)),population:Math.round(state.regions.reduce((s,r)=>s+r.resources.population,0)),industrialMaterials:Math.round(state.regions.reduce((s,r)=>s+r.resources.industrialMaterials,0))};state.global.computeLayers={general:Math.round(sumLayer('computeLayers')/5),aiTraining:Math.round(sumLayer('computeLayers')/5),aiInference:Math.round(sumLayer('computeLayers')/5),research:Math.round(sumLayer('computeLayers')/5),military:Math.round(sumLayer('computeLayers')/5)};state.global.productivityLayers={industrialAutomation:Math.round(state.regions.reduce((s,r)=>s+r.productivityLayers.industrialAutomation,0)/8),agriculturalAutomation:Math.round(state.regions.reduce((s,r)=>s+r.productivityLayers.agriculturalAutomation,0)/8),researchEfficiency:Math.round(state.regions.reduce((s,r)=>s+r.productivityLayers.researchEfficiency,0)/8),militaryAI:Math.round(state.regions.reduce((s,r)=>s+r.productivityLayers.militaryAI,0)/8),administrationEfficiency:Math.round(state.regions.reduce((s,r)=>s+r.productivityLayers.administrationEfficiency,0)/8),medicalProductivity:Math.round(state.regions.reduce((s,r)=>s+r.productivityLayers.medicalProductivity,0)/8)};state.global.energy=Math.round(state.regions.reduce((s,r)=>s+r.energy,0)/8);state.global.compute=Math.round(state.regions.reduce((s,r)=>s+r.compute,0));state.global.productivity=Math.round(state.regions.reduce((s,r)=>s+r.productivity,0)/8);state.global.stability=Math.round(state.regions.reduce((s,r)=>s+r.stability,0)/8);state.global.socialCapability=Math.round(state.regions.reduce((s,r)=>s+r.socialCapability,0)/8);state.global.quarterReport={power:p,consumption,available,shortage:state.global.power.shortage,compute:state.global.compute,productivity:state.global.productivity};return state.global.quarterReport}
