function tone(id){return factionTone[id]||'#b7ff42'}
function renderMenu(){root.innerHTML=`<main class="app menu-screen"><section class="menu-hero"><div class="brand-mark">Σ/∞</div><p class="eyebrow">战略态势系统 / 2096</p><h1>奇点<br>之后</h1><p>当计算基础设施成为世界的骨骼，谁控制能源、城市与模型，谁就定义下一条历史。</p></section><section class="menu-panel"><div class="menu-card"><span>NEW CAMPAIGN</span><strong>选择你的政治接口</strong><em>进入地图后，世界本身就是你的操作面板。</em></div><div class="faction-choice-list">${Object.keys(factionNames).map(id=>`<button class="faction-choice" style="--tone:${tone(id)}" data-action="faction" data-faction="${id}" aria-pressed="${state.selectedFaction===id}"><span>${id}</span><strong>${factionNames[id]}</strong><em>${factionProfiles[id]}</em></button>`).join('')}</div><div class="menu-actions"><button class="primary-button" data-action="start">进入全球态势图 →</button></div></section></main>`}
function renderSvg(){const m=mapModes[state.mapMode];const regions=state.regions.map(r=>{const selected=state.selectedObject.kind==='region'&&state.selectedObject.id===r.id;const fill=state.mapMode==='political'?tone(r.faction):`color-mix(in srgb, ${m.value(r)>75?'#b7ff42':m.value(r)>55?'#ffc04d':'#ff5c3f'} 68%, #13231e)`;return `<path class="map-region ${selected?'is-selected':''}" style="--region-color:${fill}" d="${regionShape[r.id]}" data-region="${r.id}" tabindex="0"><title>${r.name} · ${m.metric(r)}</title></path>`}).join(''); const nodes=objectCatalog.map(o=>{const selected=state.selectedObject.kind==='object'&&state.selectedObject.id===o.id;return `<g class="map-node ${selected?'is-selected':''}" data-object="${o.id}" transform="translate(${o.x} ${o.y})" tabindex="0"><circle r="18"></circle><text y="6">${o.icon}</text><text class="node-label" y="34">${o.label}</text></g>`}).join('');return `<svg class="strategic-map" viewBox="0 0 1100 600" aria-label="世界战略地图" style="--map-x:${state.mapView.x}px;--map-y:${state.mapView.y}px;--map-scale:${state.mapView.scale}"><defs><filter id="glow"><feGaussianBlur stdDeviation="4" result="blur"/><feMerge><feMergeNode in="blur"/><feMergeNode in="SourceGraphic"/></feMerge></filter></defs><rect width="1100" height="600" fill="#10241e"/><g class="map-grid">${Array.from({length:12},(_,i)=>`<path d="M${i*100} 0V600"/>`)}${Array.from({length:7},(_,i)=>`<path d="M0 ${i*100}H1100"/>`)}</g><g class="routes"><path d="M230 135 L405 275 L700 285 L820 380"/><path d="M175 305 L405 275 L545 425 L350 465"/><path d="M405 275 L940 505"/></g><g class="map-territory">${regions}</g><g class="map-labels">${state.regions.map(r=>`<text x="${r.id==='north'?220:r.id==='west'?145:r.id==='central'?390:r.id==='east'?665:r.id==='south'?330:r.id==='desert'?535:r.id==='frontier'?785:925}" y="${r.id==='north'?185:r.id==='west'?350:r.id==='central'?330:r.id==='east'?340:r.id==='south'?500:r.id==='desert'?470:r.id==='frontier'?445:540}">${r.name}</text>`).join('')}</g><g class="map-objects">${nodes}</g></svg>`}
function renderFactionList(){return state.factions.map(f=>`<article class="faction-card ${f.id===state.playerFaction?'faction-card--player':''}" style="--tone:${tone(f.id)}"><span>${f.id}${f.id===state.playerFaction?' / PLAYER':''}</span><strong>${factionNames[f.id]}</strong><div class="meter" style="--value:${f.power}%"><i></i></div><small>影响力 ${f.power}% · 凝聚度 ${f.cohesion}%</small><em class="faction-action">${f.lastAction}</em></article>`).join('')}
function detail(){const obj=state.selectedObject.kind==='object'?objectById(state.selectedObject.id):null;const r=selectedRegion();if(!r)return '';const title=obj?.name||r.name;const type=obj?({city:'城市',power:'发电设施',compute:'数据中心',industry:'工业设施',research:'科研设施',military:'军事设施'}[obj.type]||'地图对象'):'地区';const p=r.power||{production:0,consumption:0,available:0,shortage:0};return `<div class="panel-head"><span class="eyebrow">SELECTED OBJECT / ${type}</span><h2>${title}</h2></div><section class="detail-panel"><p class="controller-line">所属国家：${factionNames[r.faction]} · 控制阵营：${factionNames[obj?.control||r.faction]}</p><div class="detail-grid"><div><span>可用电力</span><strong>${p.available} / ${p.consumption}</strong></div><div><span>电力缺口</span><strong>${p.shortage}</strong></div><div><span>可用算力</span><strong>${fmt(r.compute)} PF</strong></div><div><span>AI 转换</span><strong>${Math.round((r.productivityLayers?.industrialAutomation||0))}%</strong></div><div><span>生产状态</span><strong>${r.productivity}%</strong></div><div><span>社会能力</span><strong>${r.socialCapability||0}</strong></div></div>${!obj?`<div class="orders"><button class="order-button" data-action="order" data-order="build">▤ 建设</button><button class="order-button" data-action="order" data-order="collect">◈ 征收</button><button class="order-button" data-action="order" data-order="stabilize">◎ 稳定</button><button class="order-button" data-action="order" data-order="audit">⌬ 审计</button></div>`:`<div class="object-note"><span class="eyebrow">INFRASTRUCTURE NODE</span><p>该节点连接 ${r.name} 的战略网络，可在对应地图模式下查看其贡献。</p></div>`}</section>`}
function renderGame(){syncGlobal();const m=mapModes[state.mapMode];root.innerHTML=`<main class="app game-screen"><header class="topbar"><div class="topbar-brand"><div class="brand-mark">Σ/∞</div><strong>奇点之后</strong></div><div class="readouts"><div class="readout" style="--tone:var(--cyan)"><span>电力</span><strong>${state.global.energy}%</strong></div><div class="readout" style="--tone:var(--pink)"><span>算力</span><strong>${fmt(state.global.compute)} PF</strong></div><div class="readout" style="--tone:var(--green)"><span>生产力</span><strong>${state.global.productivity}%</strong></div><div class="readout" style="--tone:var(--amber)"><span>稳定</span><strong>${state.global.stability}%</strong></div></div><div class="turn-box"><span>时间 / 2096.03.${String(state.turn).padStart(2,'0')}</span><strong>回合 ${state.turn}</strong></div></header><aside class="left-panel"><div class="panel-head"><span class="eyebrow">FACTION NETWORK</span><h2>阵营态势</h2></div><div class="faction-list">${renderFactionList()}</div></aside><section class="map-stage" data-map-stage><div class="map-caption"><span class="eyebrow">WORLD MAP / ${m.label}</span><strong>${m.description}</strong></div><div class="map-controls"><button data-action="zoom" data-value="-1" aria-label="缩小">−</button><button data-action="zoom" data-value="reset">1:1</button><button data-action="zoom" data-value="1" aria-label="放大">+</button></div>${renderSvg()}<div class="map-legend"><i style="background:${tone(state.playerFaction)}"></i>${factionNames[state.playerFaction]}<span>当前模式：${m.label}</span></div></section><aside class="right-panel">${detail()}<div class="log-panel"><span class="eyebrow">EVENT LOG</span>${state.log.map(x=>`<p>${x}</p>`).join('')}</div></aside><footer class="bottom-bar"><div class="bottom-note"><span>地图模式</span><strong>${m.icon} ${m.label}</strong></div><div class="mode-bar">${Object.entries(mapModes).map(([id,x])=>`<button class="mode-button ${state.mapMode===id?'is-active':''}" data-action="mode" data-mode="${id}"><b>${x.icon}</b><span>${x.label}</span></button>`).join('')}</div><button class="next-button" data-action="next">推进时间 →</button></footer></main>`}
const baseDetail=detail;detail=function(){if(state.selectedObject.kind!=='object')return baseDetail();const o=objectById(state.selectedObject.id),n=nodeModel(o),r=regionById(o.regionId);return `<div class="panel-head"><span class="eyebrow">INFRASTRUCTURE NODE / ${n.category}</span><h2>${n.name}</h2></div><section class="detail-panel"><p class="controller-line">${n.subtype} · ${n.status} · 所属地区：${r.name}</p><div class="control-matrix"><div><span>土地控制者</span><strong>${factionNames[n.control.land]}</strong></div><div><span>政治控制者</span><strong>${factionNames[n.control.political]}</strong></div><div><span>经济控制者</span><strong>${factionNames[n.control.economic]}</strong></div><div><span>技术控制者</span><strong>${factionNames[n.control.technical]}</strong></div><div><span>工人影响</span><strong>${factionNames[n.control.worker]}</strong></div></div><div class="detail-grid"><div><span>电力输入 / 输出</span><strong>${n.powerIn} / ${n.powerOut}</strong></div><div><span>算力输入 / 输出</span><strong>${n.computeIn} / ${n.computeOut}</strong></div><div><span>生产能力</span><strong>${n.production}</strong></div><div><span>当前事件</span><strong>${n.event}</strong></div><div><span>节点电力状态</span><strong>${n.energyState}%</strong></div><div><span>阵营影响</span><strong>${factionNames[n.control.economic]}</strong></div></div><div class="object-note"><span class="eyebrow">MULTIPLE CONTROL</span><p>土地、政治、经济、技术与工人控制可以属于不同力量。这是生产资料网络的核心冲突。</p></div></section>`};
const detailWithNode=detail;detail=function(){const html=detailWithNode();if(state.selectedObject.kind!=='object')return html;return html.replace('</section>','<div class="conflict-actions"><button data-action="conflict" data-conflict="protect">保护节点</button><button data-action="conflict" data-conflict="cutGrid">切断电网</button><button data-action="conflict" data-conflict="sabotageData">破坏节点</button><button data-action="conflict" data-conflict="occupyData">占领节点</button><button data-action="conflict" data-conflict="strike">劳工运动</button><button data-action="conflict" data-conflict="nationalize">国家接管</button></div></section>')};
function render(){state.screen==='menu'?renderMenu():renderGame()}
function applyOrder(order){const r=selectedRegion();if(!r)return;if(order==='build'){r.productivity=clamp(r.productivity+7,0,100);r.energy=clamp(r.energy-2,0,100);pushLog(`${r.name}：完成基础设施建设，生产力上升。`)}if(order==='collect'){state.global.data+=4;r.political=clamp(r.political-2,0,100);pushLog(`${r.name}：征收协议执行，数据储备增加。`)}if(order==='stabilize'){r.stability=clamp(r.stability+8,0,100);pushLog(`${r.name}：稳定行动完成，社会张力下降。`)}if(order==='audit'){r.compute+=12;r.influence=clamp(r.influence+4,0,100);pushLog(`${r.name}：算力审计发现隐藏节点。`)}render()}
function factionScore(f,r){const w=f.doctrine.weights;return (w.compute||0)*r.compute+(w.powerPlants||0)*r.infrastructure.powerPlants*12+(w.powerGrid||0)*r.infrastructure.powerGrid*10+(w.dataCenters||0)*r.infrastructure.dataCenters*14+(w.chipFactories||0)*r.infrastructure.chipFactories*9+(w.research||0)*r.technology*2+(w.automation||0)*r.productivity*2+(w.stability||0)*r.stability+(w.revolution||0)*(100-r.political)+(w.labor||0)*(100-r.stability)}
function chooseFactionTarget(f){return state.regions.slice().sort((a,b)=>factionScore(f,b)-factionScore(f,a))[0]||state.regions[0]}
function runFactionAI(){const reports=[];state.factions.forEach(f=>{const target=chooseFactionTarget(f);f.target=target.id;let action='buildPower';const w=f.doctrine.weights;if((w.dataCenters||0)>=4)action='buildCompute';if((w.chipFactories||0)>=4)action='buildChip';if((w.research||0)>=4)action='buildResearch';if((w.powerGrid||0)>=4)action='secureGrid';if((w.labor||0)>=4)action='organizeLabor';if((w.automation||0)>=4)action='expandAutomation';if((w.technology||0)>=4)action='shareTechnology';if(action==='buildPower')target.infrastructure.powerPlants=clamp(target.infrastructure.powerPlants+1,1,12);if(action==='buildCompute')target.infrastructure.dataCenters=clamp(target.infrastructure.dataCenters+1,1,12);if(action==='buildChip')target.infrastructure.chipFactories=clamp(target.infrastructure.chipFactories+1,1,10);if(action==='buildResearch')target.technology=clamp(target.technology+4,0,100);if(action==='secureGrid')target.infrastructure.powerGrid=clamp(target.infrastructure.powerGrid+1,1,10);if(action==='organizeLabor'){target.stability=clamp(target.stability+3,0,100);target.political=clamp(target.political-2,0,100)}if(action==='expandAutomation')target.productivity=clamp(target.productivity+4,0,100);if(action==='shareTechnology'){state.regions.forEach(r=>{r.technology=clamp(r.technology+1,0,100)});f.power=clamp(f.power+2,0,100)}f.lastAction=factionActions[action];reports.push(`${f.doctrine.name}：${f.lastAction} → ${target.name}`)});return reports}
const eventDeck=[
 {id:'data-strike',title:'数据中心工人罢工',text:'电力紧张、数据中心过载，工人组织要求获得节点控制权。',condition:()=>state.global.power.shortage>0&&state.regions.some(r=>r.infrastructure.dataCenters>=3&&r.stability<65),choices:[{label:'承认工人代表权',run:()=>{state.regions.forEach(r=>{if(r.infrastructure.dataCenters>=3)r.stability=clamp(r.stability+8,0,100)});setRelation('commons',state.playerFaction,12)}},{label:'请求天穹接管',run:()=>{state.regions.forEach(r=>{if(r.infrastructure.dataCenters>=3)r.productivity=clamp(r.productivity+5,0,100)});setRelation('consortium',state.playerFaction,10)}}]},
 {id:'antitrust',title:'反垄断危机',text:'算力集中度过高，多个地区要求拆分天穹的基础设施控制权。',condition:()=>state.factions.find(f=>f.id==='consortium')?.power>86&&state.global.compute>500,choices:[{label:'拆分关键节点',run:()=>{state.factions.find(f=>f.id==='consortium').power-=8;state.regions[2].infrastructure.dataCenters=clamp(state.regions[2].infrastructure.dataCenters-1,0,12);state.history.push('antitrust-resolved')}},{label:'维持市场秩序',run:()=>{state.global.stability=clamp(state.global.stability-6,0,100);setRelation('consortium',state.playerFaction,12)}}]},
 {id:'automation-wave',title:'自动化浪潮下的工人运动',text:'工业自动化提高产出，也让大量劳动者失去谈判能力。',condition:()=>state.regions.some(r=>r.productivity>80&&r.stability<60),choices:[{label:'建立再培训体系',run:()=>{state.regions.forEach(r=>{r.stability=clamp(r.stability+6,0,100);r.productivity=clamp(r.productivity+2,0,100)})}},{label:'扩大自动化部署',run:()=>{state.regions.forEach(r=>{r.productivity=clamp(r.productivity+8,0,100);r.stability=clamp(r.stability-10,0,100)})}}]}
];
const policyTrees={consortium:[['capital-expansion','资本扩张',()=>true,()=>{state.factions.find(f=>f.id==='consortium').power+=4}],['compute-monopoly','算力垄断',()=>state.global.compute>700,()=>{state.factions.find(f=>f.id==='consortium').power+=8}],['ai-automation','AI 自动化',()=>state.global.productivity>75,()=>state.regions.forEach(r=>r.productivity=clamp(r.productivity+5,0,100))],['global-control','全球控制',()=>state.factions.find(f=>f.id==='consortium').power>90&&state.global.compute>900,()=>state.history.push('consortium-global-control')]],union:[['state-concentration','国家集中',()=>true,()=>state.regions.forEach(r=>r.infrastructure.powerGrid=clamp(r.infrastructure.powerGrid+1,1,10))],['energy-nationalization','能源国有化',()=>state.regions.filter(r=>r.faction==='union').length>=2,()=>state.regions.filter(r=>r.faction==='union').forEach(r=>r.infrastructure.powerPlants++ )],['control-consortium','控制天穹',()=>state.diplomacy.relations['union:consortium']<0,()=>setRelation('union','consortium',20)],['state-compute','国家算力体系',()=>state.global.power.available>500&&state.global.compute>650,()=>state.history.push('union-state-compute')]],covenant:[['research-breakthrough','科研突破',()=>state.global.productivityLayers.researchEfficiency>55,()=>state.regions.forEach(r=>r.technology=clamp(r.technology+6,0,100))],['new-computing','新型计算',()=>state.global.compute>700,()=>state.regions.forEach(r=>r.infrastructure.cooling++ )],['efficiency-revolution','算力效率革命',()=>state.global.power.available>state.global.power.consumption,()=>state.global.compute+=80],['public-technology','技术公共化',()=>state.history.includes('antitrust-resolved'),()=>state.history.push('covenant-public-tech')]],commons:[['labor-organization','劳工组织',()=>true,()=>state.regions.forEach(r=>r.stability=clamp(r.stability+4,0,100))],['infrastructure-struggle','基础设施斗争',()=>state.infrastructureConflicts.length>=2,()=>state.history.push('commons-infrastructure-struggle')],['revolution','革命',()=>state.global.stability<65&&state.infrastructureConflicts.length>=4,()=>state.regions.forEach(r=>r.political=clamp(r.political-10,0,100))],['production-reorg','生产资料重组',()=>state.history.includes('commons-infrastructure-struggle'),()=>state.history.push('commons-reorganized')]],frontier:[['national-ai','国家 AI 计划',()=>true,()=>state.regions.forEach(r=>r.infrastructure.dataCenters++ )],['industrial-automation','工业自动化',()=>state.global.productivity>70,()=>state.regions.forEach(r=>r.productivity=clamp(r.productivity+7,0,100))],['high-productivity','高度生产力',()=>state.global.compute>800,()=>state.global.productivity=clamp(state.global.productivity+10,0,100)],['social-transition','社会转型',()=>state.global.socialCapability>70,()=>state.history.push('frontier-social-transition')]]};
const conflictActions={cutGrid:'切断电网',sabotageData:'破坏数据中心',seizePower:'争夺能源基地',chipBlockade:'芯片封锁',networkAttack:'通信网络攻击',occupyData:'数据中心占领',protect:'基础设施保护',strike:'劳工运动',nationalize:'国家接管'};
function relationKey(a,b){return `${a}:${b}`}
function setRelation(a,b,delta){const k=relationKey(a,b);state.diplomacy.relations[k]=clamp((state.diplomacy.relations[k]||0)+delta,-100,100);state.diplomacy.relations[relationKey(b,a)]=state.diplomacy.relations[k]}
function diplomacyAction(type,targetFaction){const p=state.playerFaction;const k=relationKey(p,targetFaction);if(type==='trade'||type==='energyTrade'||type==='computeTrade'){state.diplomacy.tradeRoutes.push({from:p,to:targetFaction,type,turn:state.turn});setRelation(p,targetFaction,8);state.diplomacy.lastAction=`${factionNames[p]} 与 ${factionNames[targetFaction]} 建立${type==='trade'?'资源':type==='energyTrade'?'能源':'算力'}交易`}if(type==='cooperate'){state.diplomacy.treaties.push({a:p,b:targetFaction,type:'technology',turn:state.turn});setRelation(p,targetFaction,15);state.diplomacy.lastAction=`${factionNames[p]} 与 ${factionNames[targetFaction]} 签署技术合作`}if(type==='sanction'||type==='blockade'){state.diplomacy.sanctions.push({from:p,to:targetFaction,type,turn:state.turn});setRelation(p,targetFaction,-18);state.diplomacy.lastAction=`${factionNames[p]} 对 ${factionNames[targetFaction]} 实施${type==='sanction'?'制裁':'技术封锁'}`}if(type==='alliance'){state.diplomacy.treaties.push({a:p,b:targetFaction,type:'alliance',turn:state.turn});setRelation(p,targetFaction,25);state.diplomacy.lastAction=`${factionNames[p]} 与 ${factionNames[targetFaction]} 结成同盟`}pushLog(state.diplomacy.lastAction);render()}
function infrastructureConflict(action,nodeId){const o=objectById(nodeId),r=regionById(o?.regionId);if(!o||!r)return;const attacker=state.playerFaction;const targetFaction=o.control;const conflict={action,nodeId,attacker,target:targetFaction,turn:state.turn};state.infrastructureConflicts.push(conflict);state.nodeSecurity[nodeId]=action==='protect'?90:Math.max(0,(state.nodeSecurity[nodeId]||70)-25);if(action==='cutGrid'){r.infrastructure.powerGrid=clamp(r.infrastructure.powerGrid-1,1,10);r.energy=clamp(r.energy-18,0,100)}if(action==='sabotageData'||action==='occupyData'){r.infrastructure.dataCenters=clamp(r.infrastructure.dataCenters-(action==='sabotageData'?1:0),0,12);r.compute=clamp(r.compute-22,0,999)}if(action==='seizePower'){r.infrastructure.powerPlants=clamp(r.infrastructure.powerPlants-1,1,12);r.energy=clamp(r.energy-12,0,100)}if(action==='chipBlockade'){r.infrastructure.chipFactories=clamp(r.infrastructure.chipFactories-1,0,10);r.technology=clamp(r.technology-8,0,100)}if(action==='networkAttack'){r.stability=clamp(r.stability-8,0,100);r.socialCapability=clamp((r.socialCapability||0)-8,0,100)}if(action==='strike'){r.productivity=clamp(r.productivity-9,0,100);r.stability=clamp(r.stability+2,0,100)}if(action==='nationalize'){o.control=attacker;r.political=clamp(r.political+5,0,100)}if(action==='protect'){r.stability=clamp(r.stability+4,0,100)}setRelation(attacker,targetFaction,action==='protect'?4:-12);pushLog(`${factionNames[attacker]}：${conflictActions[action]} → ${o.name}`);render()}
function runDiplomacyAI(){state.factions.forEach(f=>{const target=state.factions.find(other=>other.id!==f.id&&other.id===regionById(f.target)?.faction)||state.factions.find(other=>other.id!==f.id);if(!target)return;const relation=state.diplomacy.relations[relationKey(f.id,target.id)]||0;if(f.id==='covenant'&&relation>-20){setRelation(f.id,target.id,6);state.diplomacy.treaties.push({a:f.id,b:target.id,type:'technology',turn:state.turn})}else if((f.id==='consortium'||f.id==='union')&&relation<10){setRelation(f.id,target.id,-6);state.diplomacy.sanctions.push({from:f.id,to:target.id,type:'pressure',turn:state.turn})}else setRelation(f.id,target.id,2)});state.diplomacy.lastAction='阵营外交完成季度评估'}
function evaluatePolicy(){const tree=policyTrees[state.playerFaction]||[];const current=state.policyState[state.playerFaction];const next=tree.find(([id,,condition])=>!current.completed.includes(id)&&condition());if(next){current.active=next[0];next[3]();current.completed.push(next[0]);pushLog(`国策完成：${next[1]}`)}}
function evaluateEvent(){if(state.currentEvent)return;const event=eventDeck.find(e=>e.condition()&&!state.history.includes(e.id));if(event){state.currentEvent=event;pushLog(`社会事件：${event.title}`)}}
function resolveEvent(index){const event=state.currentEvent;if(!event)return;event.choices[index]?.run();state.history.push(event.id);pushLog(`事件决策：${event.title}`);state.currentEvent=null;render()}
function nextTurn(){state.turn++;state.quarter=state.quarter%4+1;const factionReports=runFactionAI();state.global.quarterReport=null;const report=settleQuarter();state.global.drift=clamp(state.global.drift+(report.shortage>0?2:-1),0,100);pushLog(report.shortage>0?`季度结算：电力缺口 ${report.shortage}，基础设施受到压制。`:`季度结算：${report.available} 单位电力驱动 ${report.compute} PF 算力，生产力循环稳定。`);factionReports.slice(0,2).forEach(pushLog);render()}
root.addEventListener('click',e=>{const b=e.target.closest('[data-action]');const reg=e.target.closest('[data-region]');const node=e.target.closest('[data-object]');if(reg){state.selectedObject={kind:'region',id:reg.dataset.region};render();return}if(node){state.selectedObject={kind:'object',id:node.dataset.object};render();return}if(!b)return;const a=b.dataset.action;if(a==='faction'){state.selectedFaction=b.dataset.faction;renderMenu()}if(a==='start'){state.playerFaction=state.selectedFaction;state.screen='game';render()}if(a==='mode'){state.mapMode=b.dataset.mode;render()}if(a==='zoom'){state.mapView.scale=b.dataset.value==='reset'?1:clamp(state.mapView.scale+(b.dataset.value==='1'?.15:-.15),.7,1.8);render()}if(a==='order')applyOrder(b.dataset.order);if(a==='next')nextTurn()});
let drag=null;root.addEventListener('pointerdown',e=>{if(e.target.closest('[data-map-stage]')&&!e.target.closest('button')){drag={x:e.clientX,y:e.clientY,ox:state.mapView.x,oy:state.mapView.y};e.currentTarget.setPointerCapture?.(e.pointerId)}});root.addEventListener('pointermove',e=>{if(drag){state.mapView.x=drag.ox+e.clientX-drag.x;state.mapView.y=drag.oy+e.clientY-drag.y;const svg=root.querySelector('.strategic-map');if(svg){svg.style.setProperty('--map-x',`${state.mapView.x}px`);svg.style.setProperty('--map-y',`${state.mapView.y}px`)}}});root.addEventListener('pointerup',()=>{drag=null});root.addEventListener('wheel',e=>{if(e.target.closest('[data-map-stage]')){e.preventDefault();state.mapView.scale=clamp(state.mapView.scale+(e.deltaY<0?.08:-.08),.7,1.8);const svg=root.querySelector('.strategic-map');if(svg)svg.style.setProperty('--map-scale',state.mapView.scale)}},{passive:false});
const priorNextTurn=nextTurn;nextTurn=function(){runDiplomacyAI();priorNextTurn();evaluatePolicy();evaluateEvent();render()};
const detailWithEvent=detail;detail=function(){let html=detailWithEvent();if(state.currentEvent){const faction=state.playerFaction;html+=`<section class="event-card" style="--event-tone:${tone(faction)}"><div class="event-poster"><span class="event-faction">${factionNames[faction]}</span><span class="event-slogan">生产资料决定未来</span><span class="event-signal">SYS / ${state.turn}.${state.quarter} / ${state.currentEvent.id}</span></div><span class="eyebrow">SYSTEMIC EVENT / 社会系统响应</span><h3>${state.currentEvent.title}</h3><p>${state.currentEvent.text}</p><div class="event-choices">${state.currentEvent.choices.map((c,i)=>`<button data-action="event" data-choice="${i}">${c.label}</button>`).join('')}</div></section>`}return html};
render();
root.addEventListener('click',e=>{const b=e.target.closest('[data-action="conflict"]');if(b&&state.selectedObject.kind==='object')infrastructureConflict(b.dataset.conflict,state.selectedObject.id)});
root.addEventListener('click',e=>{const b=e.target.closest('[data-action="event"]');if(b)resolveEvent(Number(b.dataset.choice))});
